Het nieuwe marketingprogramma van Microsoft
#include <zever.h>
#include <leugens.h>
#include <welke_programma's_heeft_de_gebruiker.h> /* Microsoft
>Network
Connectivity library */
#include <proces.h> /* Voor de rechtbank */
#define vertel(x) leugens(x)
#define pc-gebruikers WILLEN_ALLEMAAL_ONZE_ROMMEL_KOPEN
#define volgend_jaar binnenkort
#define product_klaar_om_te_verspreiden er_is_een_nieuwe_betaversie
}
void main()
}
if (laatste_windows_versie>ouder_dan_een_maand){
if (er_nog_steeds_fouten_zijn)
post(service-pak);
if (verkoop_onder_bepaald_niveau_zakt)
verspreid(GERUCHTEN_OVER_EEN_NIEUWE_FOUTLOZE_VERSIE);
}
while(iedereen_over_deze_nieuwe_versie_praat)
{
maak_valse_belofte(het_zal_multitasking_zijn_en_volledig_plug_n_play);
/*Standard Call, in leugens.h */
if (de_vakpers_zich_er_ mee_ gaat_ bemoeien)
maak_valse_belofte(volledige_integratie_web_en_desktop);
als (echt_iedereen_erover_praat)
{
market_time=rijp;
zeg("binnen 1 maand ligt het in de winkel");
geef_opdracht(programmeurs,
>repareer_geen_fouten_meer_in_oude_versie);
geef_opdracht(programmeurs,
begin_na_te_denken_over_een_nieuwe_versie);
geef_opdracht(marketingafdeling, begin_onzin_te_verspreiden);
gebakken_lucht=WAAR;
}
}
switch (vervelende_vragen_van_de_wereldpers)
{
case WANNEER_ZAL_HET_KLAAR_ZIJN:
zeg("Het zal in de winkels liggen binnen", vandaag+30_dagen ,". We
zijn de
laatste tests aan het uitvoeren.");
break;case WERKT_DIE_WEBINTEGRATIE_ WEL:
zeg("Uiteraard werkt dat!");
vraag(programmeurs, waarom_werkt_dat_niet);
pretendeer(er_is_geen_enkel_probleem);
break;
case WAT_ZIJN_DE_MINIMALE_HARDWARE_VEREISTEN:
zeg("Het draait supersnel op een 386 dankzij de vernieuwde 32-bits
architectuur")
informeer(INTEL, "verkoop MMX-processoren met kloksnelheden boven 200 Mhz gaat stijgen");
informeer(SAMSUNG, "bouw een nieuwe fabriek voor geheugenmodules want
iedereen heeft straks minimaal 64Mb RAM nodig");
informeer(QUANTUM+SEAGATE, "zorg voor grotere harde schijven");
ontvang_flinke_bonus(INTEL, SAMSUNG, QUANTUM, SEAGATE);
break;
case KRIJGT_MICROSOFT_ZO_NIET_TEVEEL_INVLOED:
zeg("Helemaal niet, we maken de wereld door dit nieuw product gewoon beter en gemakkelijker voor iedereen");
noteer(journalist, boek_van_grote_Bill);
when(het_moment_is_daar)
{
arresteer(journalist);
hersenspoel(journalist);
when(journalist_zegt_windows98_is_foutvrij)
{
geef_opdracht(journalist, schrijf_objectief_verhaal);
laat_vrij(journalist);
}
while (gebakken_lucht)
{
introductiedatum++; /* Vertraging */
if (niemand_nog_gelooft_dat_het_product_wordt_uitgebracht);
zeg("Het zal klaar zijn op ", vandaag+EEN_MAAND);
}
introduceer(preview_memphis)
while (iedereen_zo_dom_is_om_onze_rommel_te_kopen)
{
bills_bankrekening_en_aandelen=40miljard$;
verspreid(nieuwe_en_betere_betaversie);
introduceer(meer_geheugen_vereist);
if (klanten_problemen_melden_tijdens_installatie)
{
zeg("Het is geen softwareprobleem ; het ligt aan uw hardware.");
if (slimme_klant_wijst_op_plug_n_play_belofte)
{
negeer(klant);
geef_opdracht(microsoft_geheime_dienst, hou die persoon in de gaten
>en
stuur
de BSA langs);
}
if (ander_bedrijf_heeft_goed_product)
{
steel(hun_ideeën);beschuldig(ander_bedrijf, steelt_onze_ideeën);
huur(een_berg_advocaten); /* in proces.h */
wacht(tot_ander_bedrijf_geen_geld_meer_heeft_om_rechtzaak_te_betalen);
koop(ander_bedrijf);
}
/* Nu iedereen door heeft dat wij producten vol fouten tegen veel te
hoge
prijzen op de markt brengen en kwaad is op ons */
geef_opdracht(plastische_chirurg, laat_bill_een_arme_drommel_lijken);
koop(onbewoond_eiland); huur(harem);
lach_uit(iedereen,
omdat_ze_jaar_na_jaar_ziiten_te_wachten_op_onvolledige_versies);
}
void bugfix(void)
{
verspreid(win98_plus)
vraag(overdreven_veel_geld)
if (klant_zegt_dat_hij_niet_voor_deze_bugfix_wil_betalen)
{
zeg("Dit is helemaal geen bugfix, maar een aanvulling op het
standaardpakket.");
if (klant_blijft_zeuren)
{
negeer(klant);
noteer(klant, boek_van_grote_Bill);
/* We zullen hem krijgen als iedereen Billware gebruikt!!*/
(Ontvangen 28 juli 1999)

